package com.android.messaging.sms;
import android.Manifest;import android.app.Activity;import android.app.role.RoleManager;import android.content.Context;import android.content.Intent;import android.content.pm.PackageManager;import android.os.Build;import android.provider.Telephony;import java.util.ArrayList;
public final class SmsRole {public static final int REQ_ROLE=70,REQ_PERMS=71;private SmsRole(){}public static boolean isDefault(Context c){if(Build.VERSION.SDK_INT>=29){RoleManager r=(RoleManager)c.getSystemService(Context.ROLE_SERVICE);return r!=null&&r.isRoleAvailable(RoleManager.ROLE_SMS)&&r.isRoleHeld(RoleManager.ROLE_SMS);}return c.getPackageName().equals(Telephony.Sms.getDefaultSmsPackage(c));}public static void request(Activity a){if(Build.VERSION.SDK_INT>=29){RoleManager r=(RoleManager)a.getSystemService(Context.ROLE_SERVICE);if(r!=null){a.startActivityForResult(r.createRequestRoleIntent(RoleManager.ROLE_SMS),REQ_ROLE);return;}}Intent i=new Intent(Telephony.Sms.Intents.ACTION_CHANGE_DEFAULT);i.putExtra(Telephony.Sms.Intents.EXTRA_PACKAGE_NAME,a.getPackageName());a.startActivityForResult(i,REQ_ROLE);}public static boolean hasCore(Context c){return c.checkSelfPermission(Manifest.permission.READ_SMS)==PackageManager.PERMISSION_GRANTED;}public static void permissions(Activity a){ArrayList<String>m=new ArrayList<>();add(a,m,Manifest.permission.READ_SMS);add(a,m,Manifest.permission.RECEIVE_SMS);add(a,m,Manifest.permission.SEND_SMS);add(a,m,Manifest.permission.RECEIVE_MMS);add(a,m,Manifest.permission.RECEIVE_WAP_PUSH);add(a,m,Manifest.permission.READ_CONTACTS);if(Build.VERSION.SDK_INT>=33)add(a,m,Manifest.permission.POST_NOTIFICATIONS);if(!m.isEmpty())a.requestPermissions(m.toArray(new String[0]),REQ_PERMS);}private static void add(Context c,ArrayList<String>m,String p){if(c.checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)m.add(p);}}
